def analyze(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
 seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if col==bg or (r,c) in seen:continue
   st=[(r,c)];seen.add((r,c));pts=[]
   while st:
    y,x=st.pop();pts.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
      seen.add((yy,xx));st.append((yy,xx))
   r0,r1=min(y for y,x in pts),max(y for y,x in pts); c0,c1=min(x for y,x in pts),max(x for y,x in pts)
   area=(r1-r0+1)*(c1-c0+1)
   out.append((col,len(pts),(r0,r1,c0,c1),area,round(len(pts)/area,2)))
 return bg, sorted(out,key=lambda z:(z[2][0],z[2][2],z[0]))
